-- Ana dizi 'The Human Code: 2300' oldu: insanlığın kurtuluşu DNA'da, uzaylılarla temas, başrol AyShe.
-- Slug (neo-genesis-2099) bağlantılar ve videolar bozulmasın diye aynı kalır. 8 dilde metin ve 15 bölüm başlığı.
update public.series set title = 'The Human Code: 2300', status = 'published' where slug = 'neo-genesis-2099';

on conflict (series_id, lang) do update set tagline = excluded.tagline, description = excluded.description;

-- Eksik bölümleri taslak olarak ekle (var olanlara dokunmaz).
select (select id from public.series where slug = 'neo-genesis-2099'), g, 3, 'draft' from generate_series(1, 15) g
on conflict (series_id, n) do nothing;

on conflict (episode_id, lang) do update set title = excluded.title;
