insert into public.series_text (series_id, lang, tagline, description) values
  ((select id from public.series where slug = 'neo-genesis-2099'), 'tr', 'İnsanlığın kurtuluşu DNA''nda yazılı.', '2300 yılında, ölmekte olan Dünya''da kriyo uykusundan uyanan AyShe, uzaylıların milyonlarca yıl önce insan DNA''sına sakladığı bir şifreyi taşıdığını keşfeder. Beyaz maskeli bir örgüt peşindeyken, bu şifrenin hem insanlığın hem de onu yazanların kaderini belirleyeceğini öğrenir.'),
  ((select id from public.series where slug = 'neo-genesis-2099'), 'en', 'Humanity''s salvation is written in your DNA.', 'In 2300, on a dying Earth, AyShe wakes from cryosleep and discovers she carries a code that aliens hid in human DNA millions of years ago. Hunted by a white-masked order, she learns that this code will decide the fate of humanity and of those who wrote it.'),
  ((select id from public.series where slug = 'neo-genesis-2099'), 'de', 'Die Rettung der Menschheit steht in deiner DNA.', 'Im Jahr 2300 erwacht AyShe auf einer sterbenden Erde aus dem Kälteschlaf und entdeckt, dass sie einen Code in sich trägt, den Außerirdische vor Millionen von Jahren in der menschlichen DNA versteckt haben. Gejagt von einem Orden mit weißen Masken, erfährt sie, dass dieser Code über das Schicksal der Menschheit und seiner Schöpfer entscheidet.'),
  ((select id from public.series where slug = 'neo-genesis-2099'), 'fr', 'Le salut de l''humanité est écrit dans ton ADN.', 'En 2300, sur une Terre mourante, AyShe se réveille d''un cryosommeil et découvre qu''elle porte un code que des extraterrestres ont caché dans l''ADN humain il y a des millions d''années. Traquée par un ordre aux masques blancs, elle apprend que ce code décidera du destin de l''humanité et de ceux qui l''ont écrit.'),
  ((select id from public.series where slug = 'neo-genesis-2099'), 'es', 'La salvación de la humanidad está escrita en tu ADN.', 'En 2300, en una Tierra moribunda, AyShe despierta del criosueño y descubre que lleva un código que unos extraterrestres ocultaron en el ADN humano hace millones de años. Perseguida por una orden de máscaras blancas, descubre que ese código decidirá el destino de la humanidad y de quienes lo escribieron.'),
  ((select id from public.series where slug = 'neo-genesis-2099'), 'pt', 'A salvação da humanidade está escrita no seu DNA.', 'Em 2300, numa Terra moribunda, AyShe desperta do criossono e descobre que carrega um código que alienígenas esconderam no DNA humano há milhões de anos. Perseguida por uma ordem de máscaras brancas, ela descobre que esse código decidirá o destino da humanidade e de quem o escreveu.'),
  ((select id from public.series where slug = 'neo-genesis-2099'), 'ar', 'خلاص البشرية مكتوب في حمضك النووي.', 'في عام 2300، على أرض تحتضر، تستيقظ آيشه من السبات بالتبريد وتكتشف أنها تحمل شيفرة أخفتها كائنات فضائية في الحمض النووي البشري قبل ملايين السنين. وبينما تطاردها منظمة ذات أقنعة بيضاء، تعلم أن هذه الشيفرة ستحدد مصير البشرية ومصير من كتبوها.'),
  ((select id from public.series where slug = 'neo-genesis-2099'), 'hi', 'मानवता की मुक्ति तुम्हारे DNA में लिखी है।', '2300 में, मरती हुई पृथ्वी पर, AyShe क्रायो-नींद से जागती है और पाती है कि उसके भीतर एक कोड है जिसे एलियंस ने लाखों साल पहले मानव DNA में छिपाया था। सफ़ेद मुखौटों वाले एक संगठन से बचते हुए वह जानती है कि यही कोड मानवता और उसे लिखने वालों, दोनों की किस्मत तय करेगा।')
